-- Staff identity and onboarding state are changed only by checked server actions.
-- Filename generated by the Supabase CLI on the dedicated development NAS.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $function$
BEGIN
  INSERT INTO public.profiles (
    id, full_name, employee_id, role, role_id, super_admin, must_change_password
  )
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', 'New User'),
    NEW.raw_user_meta_data->>'employee_id',
    'employee',
    NULL,
    FALSE,
    TRUE
  );
  RETURN NEW;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.handle_new_user() TO service_role, supabase_auth_admin;

-- Table grants override column restrictions, so remove both before granting the
-- small set of existing self-service fields. Provisioning/deletion are server-owned.
REVOKE INSERT, UPDATE, DELETE ON TABLE public.profiles FROM PUBLIC, anon, authenticated;

DO $migration$
DECLARE
  profile_columns text;
BEGIN
  SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum)
  INTO profile_columns
  FROM pg_attribute
  WHERE attrelid = 'public.profiles'::regclass
    AND attnum > 0 AND NOT attisdropped;

  EXECUTE format(
    'REVOKE INSERT (%1$s), UPDATE (%1$s) ON TABLE public.profiles FROM PUBLIC, anon, authenticated',
    profile_columns
  );
END;
$migration$;

GRANT UPDATE (
  full_name,
  phone_number,
  avatar_url,
  emergency_contact_name,
  emergency_contact_phone,
  emergency_contact_relationship,
  secondary_emergency_contact_name,
  secondary_emergency_contact_phone,
  secondary_emergency_contact_relationship,
  employer_profile_notes,
  annual_holiday_allowance_days
) ON TABLE public.profiles TO authenticated;

-- The existing absence UI writes this field directly. Preserve that workflow
-- while applying its existing allowance permission, including team/own overrides.
CREATE OR REPLACE FUNCTION public.enforce_profile_allowance_permission()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public, pg_temp
AS $function$
DECLARE
  request_role text;
BEGIN
  IF NEW.annual_holiday_allowance_days IS NOT DISTINCT FROM OLD.annual_holiday_allowance_days THEN
    RETURN NEW;
  END IF;

  request_role := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', TRUE), ''),
    NULLIF(current_setting('request.jwt.claims', TRUE), '')::jsonb->>'role',
    current_user
  );

  IF request_role IN ('anon', 'authenticated')
     AND NOT COALESCE(public.can_actor_edit_absence_allowances(auth.uid(), NEW.id), FALSE) THEN
    RAISE EXCEPTION 'You do not have permission to change this holiday allowance'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.enforce_profile_allowance_permission() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.enforce_profile_allowance_permission() TO service_role;

DROP TRIGGER IF EXISTS enforce_profile_allowance_permission ON public.profiles;
CREATE TRIGGER enforce_profile_allowance_permission
BEFORE UPDATE OF annual_holiday_allowance_days ON public.profiles
FOR EACH ROW EXECUTE FUNCTION public.enforce_profile_allowance_permission();

COMMENT ON FUNCTION public.handle_new_user() IS
  'Creates an unprivileged profile; trusted admin provisioning assigns the authorised role afterwards.';
COMMENT ON FUNCTION public.enforce_profile_allowance_permission() IS
  'Applies existing absence allowance permissions to direct authenticated profile updates.';
